import {createActivityPlacer,activityPlaceAnchors,nearestActivityPoint} from './activity-sites.js?v=5.38';
import {isInteriorScene} from './scene-identity.js';
import {awardReciprocity,economicComment} from './economy.js?v=5.18.0';
import {residentActivity,npcRoute,advanceResident,localNpcAdvice} from './npc-routines.js?v=5.38';
import {HOUSEHOLDS,PERIODS,GRASSES,HOUSEHOLD_RHYMES} from './townlife-content.js';
import {findPath} from './navigation.js?v=5.5.0';
import {grantResonance} from './resonance-link.js';
export function lifeState(s){s.townLife??={version:1,minutes:480,day:1,parcels:{},delivered:[],care:{},talk:{}};const l=s.townLife;l.parcels??={};l.delivered??=[];l.care??={};l.talk??={};return l;}
export function dayPeriod(minutes){const hour=Math.floor(minutes/60)%24;return PERIODS.filter(p=>hour>=p.from).at(-1);}
export function tickClock(s,dt){const l=lifeState(s);l.minutes+=Math.max(0,Math.min(dt,1));if(l.minutes>=1440){l.day+=Math.floor(l.minutes/1440);l.minutes%=1440;}return l;}
export function reachableCells(scene){const start=scene.arrive||[1,1],floor=(x,y)=>scene.floor[y]?.[x]==='.';let p=floor(...start)?start:null;if(!p)for(let y=0;y<scene.height&&!p;y++)for(let x=0;x<scene.width;x++)if(floor(x,y)){p=[x,y];break;}if(!p)return[];const q=[p],seen=new Set([p.join(',')]);for(let i=0;i<q.length;i++)for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const x=q[i][0]+dx,y=q[i][1]+dy,k=x+','+y;if(floor(x,y)&&!seen.has(k)){seen.add(k);q.push([x,y]);}}return q.filter(([x,y])=>!scene.objects.some(o=>o.xy&&Math.hypot(o.xy[0]-x,o.xy[1]-y)<2)&&!scene.doors.some(o=>Math.hypot(o.xy[0]-x,o.xy[1]-y)<2));}
function silent(w,pages,choices){w.state.mode='dialog';w.callbacks.onDialog({pages:Array.isArray(pages)?pages:[pages],silent:true,choices:choices?.map(([label,action])=>({label,action:()=>{w.state.mode='field';action();}})),after:()=>{w.state.mode='field';}});}
export function installTownLife(world){
 const cache=new Map(),originalObjects=world.objects.bind(world),originalInteract=world.interact.bind(world);
 function records(){
  const scene=world.scene;if(cache.has(scene))return cache.get(scene);
  const f=HOUSEHOLDS.find(f=>f.scene===scene.location);if(!f){cache.set(scene,[]);return [];}
  const cells=reachableCells(scene);if(cells.length<10){cache.set(scene,[]);return [];}
  const original=originalObjects(),placed=[],placer=createActivityPlacer(scene,cells,original),list=[],hour=lifeState(world.state).minutes/60;
  const at=hour<6||hour>=22?0:hour>=8&&hour<12||hour>=14&&hour<18?1:2;
  const pick=(role,index,target,{reserve=true,activity=''}={})=>{
   let chosen=placer.pick(role,index,{reserve,activity,target});if(!chosen){chosen=nearestActivityPoint(scene,cells,target,{occupied:[...original,...(reserve?placed:[])],role});if(chosen&&reserve)placer.reserve(chosen,role);}
   if(chosen&&reserve)placed.push({xy:chosen,lifeKind:role});return chosen;
  };
  for(let member=0;member<f.names.length;member++){
   const role=f.roles[member],places=activityPlaceAnchors(scene,original,role),offset=member===0?[-1.1,0]:member===1?[1.1,0]:[0,1.4];
   const targets=['home','work','common'].map(kind=>[places[kind][0]+offset[0],places[kind][1]+offset[1]]);
   const anchors=targets.map((target,j)=>pick('resident',member*3+j,target,{reserve:false,activity:role}));
   if(anchors.some(p=>!p))continue;
   const xy=pick('resident',member,anchors[at],{activity:role});if(!xy)continue;
   list.push({type:'npc',life:true,lifeKind:'resident',family:f,member,name:f.names[member],label:f.names[member]+' · '+role,sprite:(HOUSEHOLDS.indexOf(f)*2+member)%7,xy,anchors,path:[],period:'',activitySites:places.features});
  }
  const animalNames={dog:['Biscuit','Spanner','Drizzle','Postage','Tether','Bran','Puddle','Mallow','Patch','Boots','Glimmer','Toast'],cat:['Thimble','Soot','Purl','Carbon','Smudge','Twig','Button','Marigold','Spool','Mittens','Prism','Ember'],cow:['Clover','Daisy','Cloud','Pearl','Hazel','Professor','Willow','Buttercup','Dottie','Moss','Opal','Nutmeg']};
  const home=activityPlaceAnchors(scene,original);
  for(const [i,kind]of ['dog','cat',...(['vale','moss','silt'].includes(f.id)?['cow']:[])].entries()){
   const center=kind==='cow'?home.plant:home.pet,xy=pick('pet',i,[center[0]+(i-1)*1.4,center[1]+(kind==='cat'?-1.6:.7)]);if(!xy)continue;
   const local=cells.filter(p=>Math.hypot(p[0]-xy[0],p[1]-xy[1])<=3.5),anchors=[[xy[0],xy[1]],[xy[0]+1.4,xy[1]+.8],[xy[0]-1.2,xy[1]+1.4]].map(p=>nearestActivityPoint(scene,local,p,{occupied:[...original,...list],role:'pet'})||xy.slice());
   list.push({type:'life',life:true,lifeKind:kind,family:f,name:animalNames[kind][HOUSEHOLDS.indexOf(f)],label:kind==='dog'?'Household dog':kind==='cat'?'Household cat':'Milk cow',xy,anchors,path:[],period:''});
  }
  let garden=null;
  if(!scene.interior&&!['chapel','office','letter_attic','lens_workshop','relief_store','lowbank_shelter'].includes(scene.key))for(const [grass,g]of GRASSES.entries()){
   const origin=garden||home.plant,target=[origin[0]+(grass%3-1)*1.3,origin[1]+Math.floor(grass/3)*1.2],xy=pick('plant',grass,target);if(xy&&!garden)garden=xy.slice();if(xy)list.push({type:'life',life:true,lifeKind:'grass',grass,label:g.name,xy});
  }
  cache.set(scene,list);return list;
 }

world.objects=()=>[...originalObjects(),...records()];world.townLife={records,update(dt){const l=tickClock(world.state,dt),period=dayPeriod(l.minutes);for(const o of records()){if(o.lifeKind==='grass')continue;const key=period.name+Math.floor(l.minutes/60);if(o.period!==key&&!o.guiding){o.period=key;const hour=l.minutes/60,index=hour<6||hour>=22?0:hour>=8&&hour<12||hour>=14&&hour<18?1:2;o.activity=o.lifeKind==='resident'?residentActivity(o,period):o.lifeKind==='cow'?(index===1?'grazing':'chewing cud'):o.lifeKind==='cat'?(index===1?'napping in a warm corner':'patrolling for mice'):(index===0?'sleeping by the household':'checking familiar smells');o.path=npcRoute(world.scene,o,o.anchors[index],world.objects());}if(o.lifeKind==='cat'&&period.name==='Morning')continue;if(o.lifeKind==='resident'){advanceResident(world,o,dt,world.objects());continue;}if(o.path.length){const p=o.path[0],dx=p[0]-.5-o.xy[0],dy=p[1]-.5-o.xy[1],d=Math.hypot(dx,dy),step=dt*(o.lifeKind==='cow'?.35:o.lifeKind==='dog'?.9:.62);if(d<=step){o.xy=[p[0]-.5,p[1]-.5];o.path.shift();if(!o.path.length)o.guiding=false;}else{if(Math.abs(dx)>.01)o.facing=dx<0?-1:1;o.xy[0]+=dx/d*step;o.xy[1]+=dy/d*step;}}}},clock(){const l=lifeState(world.state),h=Math.floor(l.minutes/60),m=Math.floor(l.minutes%60);return dayPeriod(l.minutes).name+' · '+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');}};
world.interact=o=>{if(!o?.life)return originalInteract(o);if(world.state.mode!=='field')return;const s=world.state,l=lifeState(s),f=o.family,period=dayPeriod(l.minutes);if(o.lifeKind!=='resident')o.path=[];
const hidden=()=>world.scene.objects.filter(v=>['secret','cache','riddle'].includes(v.type)&&v.xy&&world.available(v)&&!world.done(v)&&(Math.hypot(v.xy[0]-o.xy[0],v.xy[1]-o.xy[1])<1.5||findPath(world.scene,[o.xy[0]+.5,o.xy[1]+.5],v.xy,1).length>0)).sort((a,b)=>Math.hypot(a.xy[0]-o.xy[0],a.xy[1]-o.xy[1])-Math.hypot(b.xy[0]-o.xy[0],b.xy[1]-o.xy[1]))[0];
if(o.lifeKind==='grass'){const g=GRASSES[o.grass];return silent(world,g.name+'\n'+g.tip,[['Gather a little fodder',()=>{const key='grass:'+s.scene+':'+o.grass;if(l.care[key]===l.day)return silent(world,'You leave the new shoots for tomorrow.');l.care[key]=l.day;l.fodder=(l.fodder||0)+1;silent(world,'You cut a small handful and leave the roots intact. Fodder tucked into the bag.');}],['Leave it growing',()=>{}]]);}
if(o.lifeKind!=='resident'){const tell=(message,choices)=>silent(world,message.replaceAll('Biscuit',o.name).replaceAll('Thimble',o.name).replaceAll('Professor',o.name),choices);const kind=o.lifeKind,lines={dog:'Biscuit sniffs your boots, considers your entire character, and sneezes. You appear to have passed.',cat:'Thimble sits on the warmest available patch of ground. The town’s most successful property owner.',cow:'Professor turns a patient eye on you. She has the expression of someone who has already heard the question.'};return tell(o.name+' · '+(o.activity||'resting')+'\n'+lines[kind].replaceAll('Biscuit',o.name).replaceAll('Thimble',o.name).replaceAll('Professor',o.name),[[kind==='cow'?'Offer fodder':'Sit quietly beside '+o.name,()=>{if(kind==='cow'){if(!(l.fodder>0))return tell('Professor looks at your empty hand, then at the grass. A concise lesson in supply chains.');l.fodder--;const key='milk:'+f.id;if(l.care[key]!==l.day){l.care[key]=l.day;s.items.tonic=(s.items.tonic||0)+1;return tell('Professor eats the fodder. Her keeper packs a restorative for the road. One tonic received.');}return tell('Professor accepts a second helping. Her keeper smiles: “She is not a vending machine, dear.”');}const key=kind+':'+f.id;l.care[key]=l.day;tell(kind==='cat'?'After a long inspection, Thimble leans against your knee. No one is watching. You stay a moment.':'Biscuit puts his head on your boot. Whatever happened on the road, for a moment you are simply someone who stayed.');}],['Watch what catches their attention',()=>{const v=hidden();if(!v)return tell(kind==='cat'?'Thimble is watching a moth. Not every mystery belongs to you.':kind==='cow'?'Professor is studying her lunch. Her conclusions remain private.':'Biscuit watches the road. Nothing hidden seems to trouble him here.');if(kind==='dog'){o.path=npcRoute(world.scene,o,v.xy,world.objects());o.guiding=true;return tell('Biscuit trots toward an unfamiliar scent, then looks back to see whether you are coming.');}const dx=v.xy[0]-o.xy[0],dy=v.xy[1]-o.xy[1],direction=(dy<-1?'north':dy>1?'south':'')+(dx<-1?'west':dx>1?'east':'');tell(o.name+' keeps glancing '+(direction||'nearby')+'. Something there has disturbed the usual smells.');}],['Leave them in peace',()=>{}]]);}
const count=l.talk[f.id+o.member]||0;l.talk[f.id+o.member]=count+1;const resolved=s.complete||s.bosses.includes(f.chapter),emotion=resolved?f.hope:f.memory,opening=o.name+' '+f.family+' · '+f.roles[o.member]+'\n'+(o.activity||period.action)+'. '+(count%3===0?f.joke:count%3===1?emotion:f.care)+(economicComment(s,f.chapter)?' '+economicComment(s,f.chapter):'');const choices=[['Ask how the household is doing',()=>silent(world,[o.member===2?o.name+': “'+f.names[0]+' and '+f.names[1]+' are my parents. They say I am helping. Mostly I am asking questions.”':o.name+': “'+f.names[1-o.member]+' is my partner. '+f.names[2]+' is our child. We are a household, not a particularly efficient committee.”',o.name+': “'+f.care+'”',o.name+': “'+emotion+'”'])],['Ask about the neighbourhood',()=>{const v=hidden();silent(world,v?o.name+': “We mend the obvious things first. The old '+(v.type==='cache'?'supply hiding places':'stonework')+' still rewards a patient eye. '+(v.xy[1]<o.xy[1]?'Try the northern side.':'Try the southern side.')+'”':o.name+': “'+(resolved?f.hope:'The roads have been uneasy. '+f.memory)+'”');}]];
if(o.member===0&&!l.delivered.includes(f.id)&&!l.parcels[f.id])choices.push(['Offer to carry '+f.parcel,()=>{l.parcels[f.id]=true;silent(world,o.name+': “For '+f.names[1]+'. '+f.care+' Thank you.”\nThe '+f.parcel+' is safely packed.');}]);if(o.member===1&&l.parcels[f.id])choices.push(['Give '+o.name+' '+f.parcel,()=>{delete l.parcels[f.id];l.delivered.push(f.id);s.items.tonic=(s.items.tonic||0)+1;grantResonance(s,{sourceId:'household:'+f.id,label:f.family+' household · a small kindness',points:1});silent(world,o.name+' opens the parcel and laughs softly. “She remembered.”\nYou receive one tonic. A household kindness adds one growth point for each character.');}]);if(o.member===2)choices.push(['Listen to their rhyme',()=>silent(world,o.name+': “'+HOUSEHOLD_RHYMES[HOUSEHOLDS.indexOf(f)]+'”\n“'+(resolved?'We can sing it loudly again. That is new.':'It is better with clapping. I am still negotiating with the cat.')+'”')]);const advice=localNpcAdvice(world,o);if(advice)choices.push([advice.type==='camp'?'Ask where the crew can rest':advice.type==='shop'?'Ask where to restock':'Ask about a local curiosity',()=>silent(world,o.name+': “'+(advice.type==='camp'?'There is a place to sit and recover nearby.':advice.type==='shop'?'The local stall is still taking customers.':'There is something worth reading nearby. Take your time with it.')+'”',[['Show me the way',()=>{world.callbacks.onWayglassTarget?.(advice);}],['Stay and look around',()=>{}]])]);choices.push(['Wish them well',()=>{}]);silent(world,opening,choices);
};return world.townLife;}
